const TOTAL_RANGES = 8381;
const RANGE_STARTS = new Uint32Array(TOTAL_RANGES);
const RANGE_ENDS = new Uint32Array(TOTAL_RANGES);
const RANGE_ASN_IDX = new Uint8Array(TOTAL_RANGES);

// Decode once at module startup (~1.5ms)
(() => {
  const records = PACKED_RANGES.split(";");
  let prevEnd = 0;
  for (let i = 0; i < records.length; i++) {
    const parts = records[i].split(",");
    const start = (prevEnd + parseInt(parts[0], 36)) >>> 0;
    const end = (start + parseInt(parts[1], 36)) >>> 0;
    RANGE_STARTS[i] = start;
    RANGE_ENDS[i] = end;
    RANGE_ASN_IDX[i] = parseInt(parts[2], 36);
    prevEnd = end;
  }
})();

/**
 * IPv6 prefix table for Meta crawlers and major cloud datacenters.
 * Checked only when the IP contains ':'.
 */
const IPV6_ASN_PREFIXES: ReadonlyArray< readonly [string, string] > = [
  // Meta / Facebook (AS32934)
  ["2a03:2880:", "32934"],
  ["2620:0:1c", "32934"],
  ["2a03:83e0:", "32934"],
  // Amazon AWS (AS16509)
  ["2600:1f", "16509"],
  ["2406:da", "16509"],
  ["2a05:d0", "16509"],
  ["2620:107:", "16509"],
  // Google Cloud (AS396982)
  ["2600:1900:", "396982"],
  ["2600:1901:", "396982"],
  // Microsoft Azure (AS8075)
  ["2603:10", "8075"],
  // DigitalOcean (AS14061)
  ["2604:a880:", "14061"],
  ["2a03:b0c0:", "14061"],
  ["2400:6180:", "14061"],
  // Hetzner (AS24940)
  ["2a01:4f8:", "24940"],
  ["2a01:4f9:", "24940"],
  ["2a01:4ff:", "24940"],
  // OVH (AS16276)
  ["2001:41d0:", "16276"],
  ["2607:5300:", "16276"],
  ["2402:1f00:", "16276"],
  // Vultr / Choopa (AS20473)
  ["2001:19f0:", "20473"],
  ["2401:c080:", "20473"],
  ["2a05:f480:", "20473"],
  // Linode / Akamai (AS63949)
  ["2600:3c0", "63949"],
  ["2400:890", "63949"],
  ["2a01:7e0", "63949"],
  // Scaleway (AS12876)
  ["2001:bc8:", "12876"],
  // Contabo (AS51167)
  ["2a02:c20", "51167"],
  ["2605:a140:", "51167"],
];

function ipv4ToUint32(ip: string): number | null {
  let acc = 0;
  let octet = 0;
  let dots = 0;
  let digits = 0;
  for (let i = 0; i < ip.length; i++) {
    const code = ip.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      octet = octet * 10 + (code - 48);
      if (octet > 255) return null;
      digits++;
    } else if (code === 46) {
      if (digits === 0 || dots === 3) return null;
      acc = ((acc << 8) | octet) >>> 0;
      octet = 0;
      digits = 0;
      dots++;
    } else {
      return null;
    }
  }
  if (dots !== 3 || digits === 0) return null;
  return ((acc << 8) | octet) >>> 0;
}

/**
 * Synchronously resolves an IP (IPv4 or IPv6) against known Meta and Cloud
 * Datacenter CIDR blocks in ~100ns with zero I/O.
 *
 * Returns the matched ASN string (e.g. "32934", "16509", "396982") or "" if
 * the IP belongs to a normal residential/mobile ISP.
 */
export function lookupStaticAsn(ip: string): string {
  if (!ip) return "";
  const trimmed = ip.trim();
  if (!trimmed) return "";

  // IPv6 check (also handles IPv4-mapped IPv6 ::ffff:a.b.c.d)
  if (trimmed.includes(":")) {
    const low = trimmed.toLowerCase();
    if (low.startsWith("::ffff:")) {
      const v4Part = low.slice(7);
      if (v4Part.includes(".")) {
        return lookupStaticAsn(v4Part);
      }
    }
    for (let i = 0; i < IPV6_ASN_PREFIXES.length; i++) {
      if (low.startsWith(IPV6_ASN_PREFIXES[i][0])) {
        return IPV6_ASN_PREFIXES[i][1];
      }
    }
    return "";
  }

  const num = ipv4ToUint32(trimmed);
  if (num === null) return "";

  let lo = 0;
  let hi = TOTAL_RANGES - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    const start = RANGE_STARTS[mid];
    if (num < start) {
      hi = mid - 1;
    } else if (num > RANGE_ENDS[mid]) {
      lo = mid + 1;
    } else {
      return ASN_TABLE[RANGE_ASN_IDX[mid]];
    }
  }
  return "";
}
